"package main

import (
	"database/sql"
	"fmt"
	"log"
	"time"

	_ "modernc.org/sqlite"
)

func main() {
	db, err := sql.Open("sqlite", "c:/imc-audio-local/local_cache.db")
	if err != nil {
		log.Fatalf("failed to open database: %v", err)
	}
	defer db.Close()

	todayStr := time.Now().Format("2006-01-02")
	fmt.Printf("--- planned_commercial_slots for %s ---\n", todayStr)

	rows, err := db.Query(`
		SELECT block_time, commercial_id, name, commercial_type, status 
		FROM planned_commercial_slots 
		WHERE play_date = $1 
		ORDER BY block_time ASC`, todayStr)
	if err != nil {
		log.Fatalf("query slots failed: %v", err)
	}
	defer rows.Close()

	counts := make(map[string]int)
	for rows.Next() {
		var blockTime, commID, name, commType, status string
		if err := rows.Scan(&blockTime, &commID, &name, &commType, &status); err != nil {
			log.Fatal(err)
		}
		counts[commType+"_"+status]++
		// Print first few slots
		if counts[commType+"_"+status] <= 3 {
			fmt.Printf("BlockTime: %s | Type: %s | Status: %s | Name: %s\n", blockTime, commType, status, name)
		}
	}

	fmt.Println("\nSummary counts:")
	for k, v := range counts {
		fmt.Printf("  %s: %d\n", k, v)
	}
}
"

