	var name, startTime, endTime string
	var musicalBlockMins int
	var customStyles, customDurations sql.NullString
	err = db.QueryRow("SELECT name, start_time, end_time, musical_block_duration_minutes, custom_durations_json, custom_styles_json FROM basic_schedules WHERE id = $1", schedID).Scan(
		&name, &startTime, &endTime, &musicalBlockMins, &customDurations, &customStyles,
	)
	if err != nil {
		log.Fatalf("query basic_schedules failed: %v", err)
	}
	fmt.Printf("Sched Name: %s | Start: %s | End: %s | BlockMins: %d\n", name, startTime, endTime, musicalBlockMins)

	var blockName string
	var interval, limit, timeAnn, temp, inst, offer int
	err = db.QueryRow("SELECT name, interval_minutes, block_limit_seconds, percentage_time_announcement, percentage_temperature, percentage_institutional, percentage_offer FROM commercial_block_configs WHERE id = $1", blockID).Scan(
		&blockName, &interval, &limit, &timeAnn, &temp, &inst, &offer,
	)
	if err != nil {
		log.Fatalf("query commercial_block_configs failed: %v", err)
	}
	fmt.Printf("Block Name: %s | Interval: %d | Limit: %d | Time%%: %d | Temp%%: %d | Inst%%: %d | Offer%%: %d\n",
		blockName, interval, limit, timeAnn, temp, inst, offer)
}
