"package main

import (
	"encoding/json"
	"fmt"
	"io"
	"log"
	"net/http"
)

type CommercialBlockConfig struct {
	ID                         string `json:"id"`
	TenantID                   string `json:"tenant_id"`
	MediaType                  string `json:"media_type"`
	Name                       string `json:"name"`
	IntervalMinutes            int    `json:"interval_minutes"`
	BlockLimitSeconds          int    `json:"block_limit_seconds"`
	PercentageTimeAnnouncement int    `json:"percentage_time_announcement"`
	PercentageTemperature      int    `json:"percentage_temperature"`
	PercentageInstitutional    int    `json:"percentage_institutional"`
	PercentageOffer            int    `json:"percentage_offer"`
}

type SyncPayload struct {
	CommercialBlockConfigs []CommercialBlockConfig `json:"commercial_block_configs"`
}

func main() {
	client := &http.Client{}
	req, err := http.NewRequest("GET", "http://192.168.15.250:8080/api/v1/sync", nil)
	if err != nil {
		log.Fatalf("failed to create request: %v", err)
	}

	req.Header.Set("X-Store-Token", "token_1_1")
	resp, err := client.Do(req)
	if err != nil {
		log.Fatalf("request failed: %v", err)
	}
	defer resp.Body.Close()

	body, err := io.ReadAll(resp.Body)
	if err != nil {
		log.Fatalf("failed to read body: %v", err)
	}

	var payload SyncPayload
	if err := json.Unmarshal(body, &payload); err != nil {
		log.Fatalf("failed to parse json: %v", err)
	}

	fmt.Println("--- Server Commercial Block Configs ---")
	for _, b := range payload.CommercialBlockConfigs {
		fmt.Printf("ID: %s | Name: %s | Int: %d | Limit: %d | Time: %d | Temp: %d | Inst: %d | Offer: %d\n",
			b.ID, b.Name, b.IntervalMinutes, b.BlockLimitSeconds, b.PercentageTimeAnnouncement, b.PercentageTemperature, b.PercentageInstitutional, b.PercentageOffer)
	}
}
"

