"package main

import (
	"encoding/json"
	"fmt"
	"io"
	"log"
	"net/http"
)

type DiagnosticWeeklyGridDay struct {
	Day             string `json:"day"`
	ScheduleName    string `json:"schedule_name"`
	BlockConfigName string `json:"block_config_name"`
}

type DiagnosticResponse struct {
	WeeklyGrid []DiagnosticWeeklyGridDay `json:"weekly_grid"`
}

func main() {
	resp, err := http.Get("http://127.0.0.1:5005/api/diagnostics")
	if err != nil {
		log.Fatalf("failed to fetch diagnostics: %v", err)
	}
	defer resp.Body.Close()

	body, err := io.ReadAll(resp.Body)
	if err != nil {
		log.Fatalf("failed to read body: %v", err)
	}

	var data DiagnosticResponse
	if err := json.Unmarshal(body, &data); err != nil {
		log.Fatalf("failed to parse json: %v", err)
	}

	fmt.Println("--- Local Weekly Grid Diagnostics ---")
	for _, day := range data.WeeklyGrid {
		fmt.Printf("Day: %s | Sched: %s | Block: %s\n", day.Day, day.ScheduleName, day.BlockConfigName)
	}
}
"

