"		// Filter eligible blocks based on block config percentages for Offers and Institutional ads
		var eligibleBlocks []string
		isOffer := (strings.ToUpper(c.Type) == "OFFER" || strings.ToUpper(c.Type) == "OFERTA")
		isInst := (strings.ToUpper(c.Type) == "INSTITUTIONAL" || strings.ToUpper(c.Type) == "INSTITUCIONAL")

		if isOffer || isInst {
			pct := blockConfig.PercentageOffer
			if isInst {
				pct = blockConfig.PercentageInstitutional
			}

			if pct <= 0 {
				eligibleBlocks = []string{}
			} else if pct >= 100 {
				eligibleBlocks = blockTimes
			} else {
				// Randomly select a subset of blockTimes matching the percentage for this specific commercial
				numToSelect := int(math.Round(float64(len(blockTimes)) * float64(pct) / 100.0))
				if numToSelect <= 0 {
					numToSelect = 1
				}
				if numToSelect > len(blockTimes) {
					numToSelect = len(blockTimes)
				}

				shuffledIndices := rand.Perm(len(blockTimes))
				selectedIndices := shuffledIndices[:numToSelect]
				sort.Ints(selectedIndices)

				for _, idx := range selectedIndices {
					eligibleBlocks = append(eligibleBlocks, blockTimes[idx])
				}
			}
		} else {
			eligibleBlocks = blockTimes
		}"

