"// checkExactTimeEvent schedules instant interrupt events if they match current hour/minute
func checkExactTimeEvent(now time.Time) (*PlayItem, error) {
	if DB == nil {
		return nil, nil
	}

	col := getWeekdayColumn(now.Weekday())
	timeStr := now.Format("15:04:00") // Check within the current minute

	var c CommercialsAndEvents
	query := fmt.Sprintf(`
		SELECT id, name, file_name, duration_seconds, cue_in, cue_out, local_path, amplify
		FROM commercials_and_events
		WHERE is_downloaded = 1
		  AND commercial_type = 'EVENT'
		  AND (event_interruption_mode = 'SOFT' OR event_interruption_mode IS NULL OR event_interruption_mode = '')
		  AND start_time = $1
		  AND (start_date IS NULL OR start_date <= date('now'))
		  AND (end_date IS NULL OR end_date >= date('now'))
		  AND %s = 1
		LIMIT 1`, col)

	var localPath sql.NullString
	var amplify sql.NullFloat64
	err := DB.QueryRow(query, timeStr).Scan(&c.ID, &c.Name, &c.FileName, &c.DurationSeconds, &c.CueIn, &c.CueOut, &localPath, &amplify)
	if err == sql.ErrNoRows {
		return nil, nil
	} else if err != nil {
		return nil, err
	}

	// Check if this event was already played in the last hour to prevent infinite loops within the same minute
	var count int
	_ = DB.QueryRow("SELECT COUNT(*) FROM play_history WHERE track_id = $1 AND played_at >= datetime('now', '-5 minutes')", c.ID).Scan(&count)
	if count > 0 {
		return nil, nil
	}

	finalPath := c.FileName
	if localPath.Valid && localPath.String != "" {
		finalPath = localPath.String
	}

	ampVal := 1.0
	if amplify.Valid {
		ampVal = amplify.Float64
	}

	item := PlayItem{
		ID:              c.ID,
		Type:            "event",
		DisplayName:     c.Name,
		FileName:        c.FileName,
		LocalPath:       finalPath,
		DurationSeconds: c.DurationSeconds,
		CueIn:           c.CueIn,
		CueOut:          c.CueOut,
		Amplify:         ampVal,
	}
	return &item, nil
}"

