// LogScheduledEventsForToday logs all active events scheduled to play today
func LogScheduledEventsForToday() {
	if DB == nil {
		return
	}

	now := time.Now()
	col := getWeekdayColumn(now.Weekday())
	dateStr := now.Format("2006-01-02")

	query := fmt.Sprintf(`
		SELECT name, start_time, event_interruption_mode, is_downloaded
		FROM commercials_and_events
		WHERE commercial_type = 'EVENT'
		  AND (start_date IS NULL OR start_date <= date('now'))
		  AND (end_date IS NULL OR end_date >= date('now'))
		  AND %s = 1
		ORDER BY start_time ASC`, col)

	rows, err := DB.Query(query)
	if err != nil {
		LogLocal("ERROR", "[Scheduler] Failed to query today's scheduled events: %v", err)
		return
	}
	defer rows.Close()

	var events []string
	for rows.Next() {
		var name, startTime, mode string
		var isDownloaded int
		if err := rows.Scan(&name, &startTime, &mode, &isDownloaded); err == nil {
			statusStr := "DOWNLOADED"
			if isDownloaded == 0 {
				statusStr = "PENDING DOWNLOAD"
			}
			if mode == "" {
				mode = "SOFT"
			}
			events = append(events, fmt.Sprintf("  - %s | Horário: %s | Modo: %s | Status: %s", name, startTime, mode, statusStr))
		}
	}

	if len(events) == 0 {
		LogLocal("INFO", "[Scheduler] Nenhum evento programado para hoje (%s).", dateStr)
	} else {
		LogLocal("INFO", "[Scheduler] %d evento(s) programado(s) para hoje (%s):", len(events), dateStr)
		for _, ev := range events {
			LogLocal("INFO", "%s", ev)
		}
	}
}

