"import re
from html.parser import HTMLParser

html_path = r"c:\imc-audio-local\painelmusicas.html"

class LinkExtractor(HTMLParser):
    def __init__(self):
        super().__init__()
        self.links = []
        self.current_tag = None
        self.current_attrs = {}
        self.data_accumulator = []

    def handle_starttag(self, tag, attrs):
        self.current_tag = tag
        self.current_attrs = dict(attrs)
        self.data_accumulator = []

    def handle_data(self, data):
        if self.current_tag == "a":
            self.data_accumulator.append(data)

    def handle_endtag(self, tag):
        if tag == "a" and self.current_attrs.get("href"):
            href = self.current_attrs["href"]
            text = "".join(self.data_accumulator).strip()
            self.links.append((text, href))
        self.current_tag = None
        self.current_attrs = {}
        self.data_accumulator = []

with open(html_path, "r", encoding="utf-8", errors="ignore") as f:
    html_content = f.read()

extractor = LinkExtractor()
extractor.feed(html_content)

print(f"Total a tags: {len(extractor.links)}")

filtered_links = []
for text, href in extractor.links:
    if "mediafire" in href.lower() or "playlist" in href.lower() or ".php" in href.lower():
        filtered_links.append((text, href))

print(f"Filtered links: {len(filtered_links)}")
for text, href in filtered_links[:50]:
    print(f"Text: {text!r} | Href: {href!r}")
"

